computeFn:
const rent = Number(annualRentIncome) || 0;
const opex = Number(annualOperatingCost) || 0;
const price = Number(propertyPrice) || 0;
const vacancy = (Number(vacancyRatePct) || 0) / 100;
const effectiveRent = rent * (1 - vacancy);
const noi = effectiveRent - opex;
const capRate = price > 0 ? (noi / price) * 100 : 0;
const grossYield = price > 0 ? (rent / price) * 100 : 0;
return { capRate, noi, grossYield, effectiveRent };
